await Test("trail evidence sanitizer redacts common secrets and truncates",async()=>{var clean=TrailEvidenceSanitizer.Sanitize("user=demo api_key=abc123 Authorization=Bearer xyz secret:shh");Check(!clean.Contains("abc123")&&!clean.Contains("xyz")&&!clean.Contains("shh")&&clean.Contains("[REDACTED]"),"secret remained in sanitized evidence");var clipped=TrailEvidenceSanitizer.Sanitize(new string('x',50),12);Check(clipped.Length<30&&clipped.Contains("TRUNCATED"),"long evidence was not truncated");await Task.CompletedTask;});
await Test("execution policy manifest accepts safe defaults",async()=>{var policy=new ExecutionPolicyManifest("execution.default.v1","*",120,3,250,15,512,true,true,["password","secret","authorization"]);Check(ExecutionPolicyManifestValidator.Validate(policy).Count==0,"safe execution policy rejected");await Task.CompletedTask;});
await Test("execution policy manifest rejects unsafe retry and limits",async()=>{var policy=new ExecutionPolicyManifest("bad","tool",0,0,90000,1,1,false,true,[]);var errors=ExecutionPolicyManifestValidator.Validate(policy);Check(errors.Count>=5&&errors.Any(x=>x.Contains("reconciliation")),"unsafe execution policy passed validation");await Task.CompletedTask;});
Console.WriteLine($"{passed}/{passed+failures.Count} contract tests passed");return failures.Count==0?0:1;
async Task Test(string name,Func<Task> run){try{await run();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failures.Add(name+": "+e.Message);Console.WriteLine("FAIL "+failures[^1]);}}
static void Check(bool b,string m){if(!b)throw new Exception(m);}
static CycleRunner Runner(IChecker c,IReflector r,int max)=>new(new Planner(),new Maker(),c,r,new JsonlTrailStore(Path.Combine(Path.GetTempPath(),"pmcro-run-"+Guid.NewGuid().ToString("N"))),max);
static CapabilityRegistration ExecutableCapability()=>new("example.tool","Example tool","1.0.0",CapabilityInterfaceKind.McpTool,"local",CapabilityStatus.Executable,"mcp://example/tool","MIT","local:test",[],["capability.invoke"],"policy/test","sha256:abc123","test-suite",DateTimeOffset.UtcNow);
static TrailFrame Frame()=>new(Guid.NewGuid().ToString("N"),"test",0,DateTimeOffset.UtcNow,"test","test","frame",new Dictionary<string,string>());
static EnterpriseTrailFrame EnterpriseFrame()=>new("1.0","org-demo","project-demo","intent-demo","run-demo","agent-demo","corr-demo","frame-demo",1,null,[],DateTimeOffset.UtcNow,"original seed","refined objective",[],null,"check","tests.local","verify","completed",["artifact:test-001"],"policy.default","allow",null,"PASS","Independent check passed",[],true,null,"validated",0.99,"test fixture",true,null);

sealed class Planner:IPlanner{public Task<ExecutionPlan> PlanAsync(CycleContext c,CancellationToken t)=>Task.FromResult(new ExecutionPlan(c.Seed.Objective,[new PlanStep("s","step",ActionRisk.LocalValidation)],["criterion"]));}
sealed class Maker:IMaker{public Task<MakeResult> MakeAsync(CycleContext c,ExecutionPlan p,CancellationToken t)=>Task.FromResult(new MakeResult([new StepResult("s",true,"ok",["evidence"])]));}
class PassChecker:IChecker{public virtual Task<CheckResult> CheckAsync(CycleContext c,ExecutionPlan p,MakeResult m,CancellationToken t)=>Task.FromResult(new CheckResult(true,1,1,true,[],["verified"]));}
sealed class FailOnceChecker:IChecker{public Task<CheckResult> CheckAsync(CycleContext c,ExecutionPlan p,MakeResult m,CancellationToken t)=>Task.FromResult(new CheckResult(c.CycleNumber>1,c.CycleNumber>1?1:0,c.CycleNumber>1?1:0,true,[],["checked"]));}
sealed class FailChecker:IChecker{public Task<CheckResult> CheckAsync(CycleContext c,ExecutionPlan p,MakeResult m,CancellationToken t)=>Task.FromResult(new CheckResult(false,0,0,true,["failed"],[]));}
sealed class PolicyFailChecker:IChecker{public Task<CheckResult> CheckAsync(CycleContext c,ExecutionPlan p,MakeResult m,CancellationToken t)=>Task.FromResult(new CheckResult(true,1,1,false,["policy violation"],["evidence"]));}
sealed class PassReflector:IReflector{public Task<Reflection> ReflectAsync(CycleContext c,CheckResult x,CancellationToken t)=>Task.FromResult(new Reflection(CycleVerdict.Accept,"pass",[],true));}
sealed class ConditionalReflector:IReflector{public Task<Reflection> ReflectAsync(CycleContext c,CheckResult x,CancellationToken t)=>Task.FromResult(x.Passed?new Reflection(CycleVerdict.Accept,"pass",[],true):new Reflection(CycleVerdict.Loop,"retry",["Improve evidence"],false));}
sealed class LoopReflector:IReflector{public Task<Reflection> ReflectAsync(CycleContext c,CheckResult x,CancellationToken t)=>Task.FromResult(new Reflection(CycleVerdict.Loop,"retry",["Constraint"],false));}

sealed class FixedRefiner(IntentRefinement result):IIntentRefiner{public Task<IntentRefinement> RefineAsync(string raw,CancellationToken ct)=>Task.FromResult(result);}
sealed class FixedFactory:ICycleRunnerFactory{public CycleRunner Create(SeedIntent seed)=>new(new Planner(),new Maker(),new PassChecker(),new PassReflector(),new JsonlTrailStore(Path.Combine(Path.GetTempPath(),"pmcro-worker-trails-"+Guid.NewGuid().ToString("N"))),2);}

sealed class RiskyPlanner:IPlanner{public Task<ExecutionPlan> PlanAsync(CycleContext c,CancellationToken t)=>Task.FromResult(new ExecutionPlan(c.Seed.Objective,[new PlanStep("install","Install external plugin",ActionRisk.ExternalCodeExecution,"plugin.install")],["plugin installed"]));}
sealed class CountingMaker:IMaker{public int Calls{get;private set;} public Task<MakeResult> MakeAsync(CycleContext c,ExecutionPlan p,CancellationToken t){Calls++;return Task.FromResult(new MakeResult([new StepResult("install",true,"installed",["evidence"])]));}}
sealed class RiskyFactory:ICycleRunnerFactory{public CycleRunner Create(SeedIntent seed)=>new(new RiskyPlanner(),new Maker(),new PassChecker(),new PassReflector(),new JsonlTrailStore(Path.Combine(Path.GetTempPath(),"pmcro-risky-trails-"+Guid.NewGuid().ToString("N"))),2);}


sealed class FixedCapabilityPolicy(ApprovalDisposition disposition):ICapabilityPolicyGate{public Task<ApprovalDecision> EvaluateAsync(CapabilityRegistration c,CapabilityInvocationRequest r,CancellationToken t)=>Task.FromResult(new ApprovalDecision(disposition,"test-policy",disposition==ApprovalDisposition.Allow?"allowed":"approval required"));}
sealed class FakeCapabilityInvoker:ICapabilityInvoker{public CapabilityInterfaceKind InterfaceKind=>CapabilityInterfaceKind.McpTool;public int Calls{get;private set;}public Task<CapabilityInvocationResult> InvokeAsync(CapabilityRegistration c,CapabilityInvocationRequest r,CancellationToken t){Calls++;return Task.FromResult(new CapabilityInvocationResult(true,"fake invocation",["test:evidence"]));}}

sealed class FixedCommandAuthorization(ApprovalDisposition disposition):ICommandAuthorizationGate<string>{public Task<ApprovalDecision> AuthorizeAsync(PmcroCommand<string> command,CancellationToken cancellationToken)=>Task.FromResult(new ApprovalDecision(disposition,"router-test-policy",disposition==ApprovalDisposition.Allow?"allowed":"approval required"));}
sealed class EchoCommandHandler:IPmcroCommandHandler<string,string>{public string CommandType=>"echo";public int Calls{get;private set;}public Task<CommandExecutionResult<string>> HandleAsync(PmcroCommand<string> command,CancellationToken cancellationToken){Calls++;return Task.FromResult(new CommandExecutionResult<string>("completed","OK","echo complete",command.Payload,["test:echo"]));}}

sealed class InMemorySkillRouteCatalog(IReadOnlyList<SkillRouteDefinition> initial):ISkillRouteCatalog{private IReadOnlyList<SkillRouteDefinition> _routes=initial;public Task<IReadOnlyList<SkillRouteDefinition>> ListAsync(CancellationToken cancellationToken=default)=>Task.FromResult(_routes);public Task SetAsync(IReadOnlyList<SkillRouteDefinition> routes){_routes=routes;return Task.CompletedTask;}}

sealed class FakeSkillDispatcher:ISkillCommandDispatcher<string,string>{public int Calls{get;private set;}public Task<CommandExecutionResult<string>> DispatchSkillAsync(SkillRouteDefinition route,PmcroCommand<string> command,CancellationToken cancellationToken){Calls++;return Task.FromResult(new CommandExecutionResult<string>("completed","OK","skill dispatched",command.Payload,["test:skill-dispatch"]));}}
